{"file_path": "harness\\runs\\single_turn_speed_price_benchmark\\results\\claude-code-deepseek-v4-pro\\claude_deepseek_v4_pro_run_05\\sdof_newmark_demo.py", "content": "import numpy as np\nimport matplotlib.pyplot as plt\nimport json\nimport csv\nimport os\n\ndef make_time_vector(dt, duration):\n    n_steps = int(duration / dt) + 1\n    return np.linspace(0.0, duration, n_steps)\n\ndef ground_acceleration(t, g=9.81):\n    ag = (0.30 * g * np.sin(2.0 * np.pi * 1.2 * t) * np.exp(-0.15 * t)\n          + 0.10 * g * np.sin(2.0 * np.pi * 3.0 * t) * np.exp(-0.20 * t))\n    return ag\n\ndef compute_damping(m, k, zeta):\n    return 2.0 * zeta * np.sqrt(m * k)\n\ndef newmark_average_acceleration(m, c, k, ag, dt, u0=0.0, v0=0.0):\n    beta = 0.25\n    gamma = 0.5\n\n    n = len(ag)\n    u = np.zeros(n)\n    v = np.zeros(n)\n    a = np.zeros(n)\n\n    u[0] = u0\n    v[0] = v0\n    a[0] = (-ag[0] * m - c * v0 - k * u0) / m\n\n    a0 = 1.0 / (beta * dt * dt)\n    a1 = gamma / (beta * dt)\n    a2 = 1.0 / (beta * dt)\n    a3 = 1.0 / (2.0 * beta) - 1.0\n    a4 = gamma / beta - 1.0\n    a5 = dt / 2.0 * (gamma / beta - 2.0)\n\n    k_eff = k + a1 * c + a0 * m\n\n    for i in range(n - 1):\n        p_eff = (-m * ag[i + 1]\n                 + m * (a0 * u[i] + a2 * v[i] + a3 * a[i])\n                 + c * (a1 * u[i] + a4 * v[i] + a5 * a[i]))\n\n        u[i + 1] = p_eff / k_eff\n\n        v[i + 1] = (a1 * (u[i + 1] - u[i])\n                    - a4 * v[i]\n                    - a5 * a[i])\n\n        a[i + 1] = (-ag[i + 1] * m - c * v[i + 1] - k * u[i + 1]) / m\n\n    return u, v, a\n\ndef compute_response_metrics(t, ag, u, v, a_rel, a_abs):\n    peak_u = np.max(np.abs(u))\n    peak_v = np.max(np.abs(v))\n    peak_a_rel = np.max(np.abs(a_rel))\n    peak_a_abs = np.max(np.abs(a_abs))\n    peak_ku = np.max(np.abs(k_global * u))\n    idx_peak_u = np.argmax(np.abs(u))\n    t_peak_u = t[idx_peak_u]\n\n    return {\n        'peak_relative_displacement': float(peak_u),\n        'peak_relative_velocity': float(peak_v),\n        'peak_relative_acceleration': float(peak_a_rel),\n        'peak_absolute_acceleration': float(peak_a_abs),\n        'peak_pseudo_base_shear': float(peak_ku),\n        'time_of_peak_displacement': float(t_peak_u),\n    }\n\ndef save_csv(path, t, ag, u, v, a_rel, a_abs):\n    with open(path, 'w', newline='') as f:\n        writer = csv.writer(f)\n        writer.writerow(['time', 'ground_acc', 'disp', 'vel', 'acc_rel', 'acc_abs'])\n        for i in range(len(t)):\n            writer.writerow([t[i], ag[i], u[i], v[i], a_rel[i], a_abs[i]])\n\ndef save_summary_json(path, metrics):\n    with open(path, 'w') as f:\n        json.dump(metrics, f, indent=2)\n\ndef plot_response(path, t, ag, u, v, a_abs):\n    fig, axes = plt.subplots(4, 1, figsize=(10, 9), sharex=True)\n\n    axes[0].plot(t, ag, linewidth=0.8)\n    axes[0].set_ylabel('Ground Acc. (m/s$^2$)')\n    axes[0].grid(True, alpha=0.3)\n\n    axes[1].plot(t, u, linewidth=0.8)\n    axes[1].set_ylabel('Displacement (m)')\n    axes[1].grid(True, alpha=0.3)\n\n    axes[2].plot(t, v, linewidth=0.8)\n    axes[2].set_ylabel('Velocity (m/s)')\n    axes[2].grid(True, alpha=0.3)\n\n    axes[3].plot(t, a_abs, linewidth=0.8)\n    axes[3].set_ylabel('Abs. Acc. (m/s$^2$)') \n    axes[3].set_xlabel('Time (s)')\n    axes[3].grid(True, alpha=0.3)\n\n    fig.suptitle('SDOF Newmark Average Acceleration Response', fontsize=13)\n    plt.tight_layout()\n    fig.savefig(path, dpi=150)\n    plt.close(fig)\n\nk_global = 200000.0\n\ndef run_analysis(output_dir='sdof_output'):\n    os.makedirs(output_dir, exist_ok=True)\n\n    m = 1000.0\n    k = 200000.0\n    zeta = 0.05\n    g = 9.81\n    dt = 0.01\n    duration = 20.0\n\n    t = make_time_vector(dt, duration)\n    ag = ground_acceleration(t, g)\n    c = compute_damping(m, k, zeta)\n\n    omega_n = np.sqrt(k / m)\n    T_n = 2.0 * np.pi / omega_n\n\n    u, v, a_rel = newmark_average_acceleration(m, c, k, ag, dt)\n    a_abs = a_rel + ag\n\n    global k_global\n    k_global = k\n    metrics = compute_response_metrics(t, ag, u, v, a_rel, a_abs)\n\n    metrics['natural_circular_frequency'] = float(omega_n)\n    metrics['natural_period'] = float(T_n)\n    metrics['damping_coefficient'] = float(c)\n\n    save_csv(os.path.join(output_dir, 'response.csv'), t, ag, u, v, a_rel, a_abs)\n    save_summary_json(os.path.join(output_dir, 'summary.json'), metrics)\n    plot_response(os.path.join(output_dir, 'response.png'), t, ag, u, v, a_abs)\n\n    for k, v in metrics.items():\n        print(f'{k}: {v:.6e}' if abs(v) < 0.1 or abs(v) >= 1000 else f'{k}: {v:.6f}')\n\n    return metrics\n\ndef main():\n    run_analysis()\n\ndef test_zero_ground_motion():\n    m = 1000.0\n    k = 200000.0\n    c = compute_damping(m, k, 0.05)\n    dt = 0.01\n    t = make_time_vector(dt, 2.0)\n    ag = np.zeros_like(t)\n    u, v, a = newmark_average_acceleration(m, c, k, ag, dt, u0=0.0, v0=0.0)\n    assert np.allclose(u, 0.0, atol=1e-12), 'Displacement should be zero for zero input'\n    assert np.allclose(v, 0.0, atol=1e-12), 'Velocity should be zero for zero input'\n\ndef test_output_shapes():\n    m = 1000.0\n    k = 200000.0\n    zeta = 0.05\n    c = compute_damping(m, k, zeta)\n    dt = 0.01\n    duration = 2.0\n    t = make_time_vector(dt, duration)\n    ag = ground_acceleration(t)\n    u, v, a = newmark_average_acceleration(m, c, k, ag, dt)\n    n_expected = int(duration / dt) + 1\n    assert len(t) == n_expected\n    assert len(u) == n_expected\n    assert len(v) == n_expected\n    assert len(a) == n_expected\n\ndef test_damping_positive():\n    c = compute_damping(1000.0, 200000.0, 0.05)\n    assert c > 0.0, 'Damping coefficient must be positive'\n\nif __name__ == '__main__':\n    main()\n"}
